/** Synapse compatibility entry point. The official v32.4.1 embed-static.min.js path returns HTTP 404. */
(function () {
  if (window.SYNAPSE_DRAWIO_RENDER_VIEWERS && window.GraphViewer) { window.SYNAPSE_DRAWIO_RENDER_VIEWERS(); return; }
  var current = document.currentScript;
  var script = document.createElement('script');
  script.src = current && current.src ? new URL('viewer-static.min.js', current.src).href : new URL('js/viewer-static.min.js', window.SYNAPSE_DRAWIO_ASSET_BASE || new URL('./drawio/', window.location.href).href).href;
  document.head.appendChild(script);
})();
